pub fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

pub fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Input is assumed non-empty per problem statement.
    let n = x.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n {
        // Safe: i < n implies in-bounds access.
        result.push(x[i]);
        i += 1;
    }

    // Ensure the returned vector length matches the input length.
    debug_assert_eq!(result.len(), n);
    result
}